// ───── world/js/primitives/point.js ─────
class Point {
   constructor(x, y) {
      this.x = x;
      this.y = y;
   }

   equals(point) {
      return this.x == point.x && this.y == point.y;
   }

   draw(ctx, { size = 18, color = "black", outline = false, fill = false } = {}) {
      const rad = size / 2;
      ctx.beginPath();
      ctx.fillStyle = color;
      ctx.arc(this.x, this.y, rad, 0, Math.PI * 2);
      ctx.fill();
      if (outline) {
         ctx.beginPath();
         ctx.lineWidth = 2;
         ctx.strokeStyle = "yellow";
         ctx.arc(this.x, this.y, rad * 0.6, 0, Math.PI * 2);
         ctx.stroke();
      }
      if (fill) {
         ctx.beginPath();
         ctx.arc(this.x, this.y, rad * 0.4, 0, Math.PI * 2);
         ctx.fillStyle = "yellow";
         ctx.fill();
      }
   }
}

// ───── world/js/primitives/segment.js ─────
class Segment {
   constructor(p1, p2, oneWay = false) {
      this.p1 = p1;
      this.p2 = p2;
      this.oneWay = oneWay;
   }

   length() {
      return distance(this.p1, this.p2);
   }

   directionVector() {
      return normalize(subtract(this.p2, this.p1));
   }

   equals(seg) {
      return this.includes(seg.p1) && this.includes(seg.p2);
   }

   includes(point) {
      return this.p1.equals(point) || this.p2.equals(point);
   }

   distanceToPoint(point) {
      const proj = this.projectPoint(point);
      if (proj.offset > 0 && proj.offset < 1) {
         return distance(point, proj.point);
      }
      const distToP1 = distance(point, this.p1);
      const distToP2 = distance(point, this.p2);
      return Math.min(distToP1, distToP2);
   }

   projectPoint(point) {
      const a = subtract(point, this.p1);
      const b = subtract(this.p2, this.p1);
      const normB = normalize(b);
      const scaler = dot(a, normB);
      const proj = {
         point: add(this.p1, scale(normB, scaler)),
         offset: scaler / magnitude(b),
      };
      return proj;
   }

   draw(ctx, { width = 2, color = "black", dash = [], cap = "butt" } = {}) {
      ctx.beginPath();
      ctx.lineWidth = width;
      ctx.strokeStyle = color;
      ctx.lineCap = cap;
      if (this.oneWay) {
         dash = [4, 4];
      }
      ctx.setLineDash(dash);
      ctx.moveTo(this.p1.x, this.p1.y);
      ctx.lineTo(this.p2.x, this.p2.y);
      ctx.stroke();
      ctx.setLineDash([]);
   }
}

// ───── world/js/primitives/polygon.js ─────
class Polygon {
   constructor(points) {
      this.points = points;
      this.segments = [];
      for (let i = 1; i <= points.length; i++) {
         this.segments.push(
            new Segment(points[i - 1], points[i % points.length])
         );
      }
   }

   static load(info) {
      return new Polygon(
         info.points.map((i) => new Point(i.x, i.y))
      );
   }

   static union(polys) {
      Polygon.multiBreak(polys);
      const keptSegments = [];
      for (let i = 0; i < polys.length; i++) {
         for (const seg of polys[i].segments) {
            let keep = true;
            for (let j = 0; j < polys.length; j++) {
               if (i != j) {
                  if (polys[j].containsSegment(seg)) {
                     keep = false;
                     break;
                  }
               }
            }
            if (keep) {
               keptSegments.push(seg);
            }
         }
      }
      return keptSegments;
   }

   static multiBreak(polys) {
      for (let i = 0; i < polys.length - 1; i++) {
         for (let j = i + 1; j < polys.length; j++) {
            Polygon.break(polys[i], polys[j]);
         }
      }
   }

   static break(poly1, poly2) {
      const segs1 = poly1.segments;
      const segs2 = poly2.segments;
      for (let i = 0; i < segs1.length; i++) {
         for (let j = 0; j < segs2.length; j++) {
            const int = getIntersection(
               segs1[i].p1,
               segs1[i].p2,
               segs2[j].p1,
               segs2[j].p2
            );

            if (int && int.offset != 1 && int.offset != 0) {
               const point = new Point(int.x, int.y);
               let aux = segs1[i].p2;
               segs1[i].p2 = point;
               segs1.splice(i + 1, 0, new Segment(point, aux));
               aux = segs2[j].p2;
               segs2[j].p2 = point;
               segs2.splice(j + 1, 0, new Segment(point, aux));
            }
         }
      }
   }

   distanceToPoint(point) {
      return Math.min(...this.segments.map((s) => s.distanceToPoint(point)));
   }

   distanceToPoly(poly) {
      return Math.min(...this.points.map((p) => poly.distanceToPoint(p)));
   }

   intersectsPoly(poly) {
      for (let s1 of this.segments) {
         for (let s2 of poly.segments) {
            if (getIntersection(s1.p1, s1.p2, s2.p1, s2.p2)) {
               return true;
            }
         }
      }
      return false;
   }

   containsSegment(seg) {
      const midpoint = average(seg.p1, seg.p2);
      return this.containsPoint(midpoint);
   }

   containsPoint(point) {
      const outerPoint = new Point(-1000, -1000);
      let intersectionCount = 0;
      for (const seg of this.segments) {
         const int = getIntersection(outerPoint, point, seg.p1, seg.p2);
         if(int){
            intersectionCount++;
         }
      }
      return intersectionCount % 2 == 1;
   }

   drawSegments(ctx) {
      for (const seg of this.segments) {
         seg.draw(ctx, { color: getRandomColor(), width: 5 });
      }
   }

   draw(
      ctx,
      { stroke = "blue", lineWidth = 2, fill = "rgba(0,0,255,0.3)", join = "miter" } = {}
   ) {
      ctx.beginPath();
      ctx.fillStyle = fill;
      ctx.strokeStyle = stroke;
      ctx.lineWidth = lineWidth;
      ctx.lineJoin = join;
      ctx.moveTo(this.points[0].x, this.points[0].y);
      for (let i = 1; i < this.points.length; i++) {
         ctx.lineTo(this.points[i].x, this.points[i].y);
      }
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
   }
}

// ───── world/js/primitives/envelope.js ─────
class Envelope {
   constructor(skeleton, width, roundness = 1) {
      if (skeleton) {
         this.skeleton = skeleton;
         this.poly = this.#generatePolygon(width, roundness);
      }
   }

   static load(info) {
      const env = new Envelope();
      env.skeleton = new Segment(info.skeleton.p1, info.skeleton.p2);
      env.poly = Polygon.load(info.poly);
      return env;
   }

   #generatePolygon(width, roundness) {
      const { p1, p2 } = this.skeleton;

      const radius = width / 2;
      const alpha = angle(subtract(p1, p2));
      const alpha_cw = alpha + Math.PI / 2;
      const alpha_ccw = alpha - Math.PI / 2;
      
      const points = [];
      const step = Math.PI / Math.max(1, roundness);
      const eps = step / 2;
      for (let i = alpha_ccw; i <= alpha_cw + eps; i += step) {
         points.push(translate(p1, i, radius));
      }
      for (let i = alpha_ccw; i <= alpha_cw + eps; i += step) {
         points.push(translate(p2, Math.PI + i, radius));
      }

      return new Polygon(points);
   }

   draw(ctx, options) {
      this.poly.draw(ctx, options);
   }
}

// ───── world/js/math/utils.js ─────
function getNearestPoint(loc, points, threshold = Number.MAX_SAFE_INTEGER) {
   let minDist = Number.MAX_SAFE_INTEGER;
   let nearest = null;
   for (const point of points) {
      const dist = distance(point, loc);
      if (dist < minDist && dist < threshold) {
         minDist = dist;
         nearest = point;
      }
   }
   return nearest;
}

function getNearestSegment(loc, segments, threshold = Number.MAX_SAFE_INTEGER) {
   let minDist = Number.MAX_SAFE_INTEGER;
   let nearest = null;
   for (const seg of segments) {
      const dist = seg.distanceToPoint(loc);
      if (dist < minDist && dist < threshold) {
         minDist = dist;
         nearest = seg;
      }
   }
   return nearest;
}

function distance(p1, p2) {
   return Math.hypot(p1.x - p2.x, p1.y - p2.y);
}

function average(p1, p2) {
   return new Point((p1.x + p2.x) / 2, (p1.y + p2.y) / 2);
}

function dot(p1, p2) {
   return p1.x * p2.x + p1.y * p2.y;
}

function add(p1, p2) {
   return new Point(p1.x + p2.x, p1.y + p2.y);
}

function subtract(p1, p2) {
   return new Point(p1.x - p2.x, p1.y - p2.y);
}

function scale(p, scaler) {
   return new Point(p.x * scaler, p.y * scaler);
}

function normalize(p) {
   return scale(p, 1 / magnitude(p));
}

function magnitude(p) {
   return Math.hypot(p.x, p.y);
}

function perpendicular(p) {
   return new Point(-p.y, p.x);
}

function translate(loc, angle, offset) {
   return new Point(
      loc.x + Math.cos(angle) * offset,
      loc.y + Math.sin(angle) * offset
   );
}

function angle(p) {
   return Math.atan2(p.y, p.x);
}

function getIntersection(A, B, C, D) {
   const tTop = (D.x - C.x) * (A.y - C.y) - (D.y - C.y) * (A.x - C.x);
   const uTop = (C.y - A.y) * (A.x - B.x) - (C.x - A.x) * (A.y - B.y);
   const bottom = (D.y - C.y) * (B.x - A.x) - (D.x - C.x) * (B.y - A.y);

   const eps = 0.001;
   if (Math.abs(bottom) > eps) {
      const t = tTop / bottom;
      const u = uTop / bottom;
      if (t >= 0 && t <= 1 && u >= 0 && u <= 1) {
         return {
            x: lerp(A.x, B.x, t),
            y: lerp(A.y, B.y, t),
            offset: t,
         };
      }
   }

   return null;
}

function lerp(a, b, t) {
   return a + (b - a) * t;
}

function lerp2D(A, B, t) {
   return new Point(lerp(A.x, B.x, t), lerp(A.y, B.y, t));
}

function invLerp(a, b, v) {
   return (v - a) / (b - a);
}

function degToRad(degree) {
   return degree * Math.PI / 180;
}

function getRandomColor() {
   const hue = 290 + Math.random() * 260;
   return "hsl(" + hue + ", 100%, 60%)";
}

function getFake3dPoint(point, viewPoint, height) {
   const dir = normalize(subtract(point, viewPoint));
   const dist = distance(point, viewPoint);
   const scaler = Math.atan(dist / 300) / (Math.PI / 2);
   return add(point, scale(dir, height * scaler));
}

