// ───── world/js/math/graph.js ─────
class Graph {
   constructor(points = [], segments = []) {
      this.points = points;
      this.segments = segments;
   }

   static load(info) {
      const points = info.points.map((i) => new Point(i.x, i.y));
      const segments = info.segments.map((i) => new Segment(
         points.find((p) => p.equals(i.p1)),
         points.find((p) => p.equals(i.p2))
      ));
      return new Graph(points, segments);
   }

   hash() {
      return JSON.stringify(this);
   }

   addPoint(point) {
      this.points.push(point);
   }

   containsPoint(point) {
      return this.points.find((p) => p.equals(point));
   }

   tryAddPoint(point) {
      if (!this.containsPoint(point)) {
         this.addPoint(point);
         return true;
      }
      return false;
   }

   removePoint(point) {
      const segs = this.getSegmentsWithPoint(point);
      for (const seg of segs) {
         this.removeSegment(seg);
      }
      this.points.splice(this.points.indexOf(point), 1);
   }

   addSegment(seg) {
      this.segments.push(seg);
   }

   containsSegment(seg) {
      return this.segments.find((s) => s.equals(seg));
   }

   tryAddSegment(seg) {
      if (!this.containsSegment(seg) && !seg.p1.equals(seg.p2)) {
         this.addSegment(seg);
         return true;
      }
      return false;
   }

   removeSegment(seg) {
      this.segments.splice(this.segments.indexOf(seg), 1);
   }

   getSegmentsWithPoint(point) {
      const segs = [];
      for (const seg of this.segments) {
         if (seg.includes(point)) {
            segs.push(seg);
         }
      }
      return segs;
   }

   dispose() {
      this.points.length = 0;
      this.segments.length = 0;
   }

   draw(ctx) {
      for (const seg of this.segments) {
         seg.draw(ctx);
      }

      for (const point of this.points) {
         point.draw(ctx);
      }
   }
}

// ───── world/js/math/osm.js ─────
const Osm = {
   parseRoads: (data) => {
      const nodes = data.elements.filter((n) => n.type == "node");
      
      const lats = nodes.map(n => n.lat);
      const lons = nodes.map(n => n.lon);

      const minLat = Math.min(...lats);
      const maxLat = Math.max(...lats);
      const minLon = Math.min(...lons);
      const maxLon = Math.max(...lons);

      const deltaLat = maxLat - minLat;
      const deltaLon = maxLon - minLon;
      const ar = deltaLon / deltaLat;
      const height = deltaLat * 111000 * 10;
      const width = height * ar * Math.cos(degToRad(maxLat));

      const points = [];
      const segments = [];
      for (const node of nodes) {
         const y = invLerp(maxLat, minLat, node.lat) * height;
         const x = invLerp(minLon, maxLon, node.lon) * width;
         const point = new Point(x, y);
         point.id = node.id;
         points.push(point);
      }

      const ways = data.elements.filter(w => w.type == "way");
      for (const way of ways) {
         const ids = way.nodes;
         for (let i = 1; i < ids.length; i++) {
            const prev = points.find((p) => p.id == ids[i - 1]);
            const cur = points.find((p) => p.id == ids[i]);
            const oneWay = way.tags.oneway || way.tags.lanes == 1;
            segments.push(new Segment(prev, cur, oneWay));
         }
      } 

      return { points, segments };
   }
}

// ───── world/js/markings/marking.js ─────
class Marking  {
   constructor(center, directionVector, width, height) {
      this.center = center;
      this.directionVector = directionVector;
      this.width = width;
      this.height = height;

      this.support = new Segment(
         translate(center, angle(directionVector), height / 2),
         translate(center, angle(directionVector), -height / 2)
      );
      this.poly = new Envelope(this.support, width, 0).poly;

      this.type = "marking";
   }

   static load(info) {
      const point = new Point(info.center.x, info.center.y);
      const dir = new Point(info.directionVector.x, info.directionVector.y);
      switch (info.type) {
         case "crossing":
            return new Crossing(point, dir, info.width, info.height);
         case "light":
            return new Light(point, dir, info.width, info.height);
         case "marking":
            return new Marking(point, dir, info.width, info.height);
         case "parking":
            return new Parking(point, dir, info.width, info.height);
         case "start":
            return new Start(point, dir, info.width, info.height);
         case "stop":
            return new Stop(point, dir, info.width, info.height);
         case "target":
            return new Target(point, dir, info.width, info.height);
         case "yield":
            return new Yield(point, dir, info.width, info.height);
      }
   }

   draw(ctx) {
      this.poly.draw(ctx);
   }
}

// ───── world/js/markings/stop.js ─────
class Stop extends Marking {
   constructor(center, directionVector, width, height) {
      super(center, directionVector, width, height);

      this.border = this.poly.segments[2];
      this.type = "stop";
   }

   draw(ctx) {
      this.border.draw(ctx, { width: 5, color: "white" });
      ctx.save();
      ctx.translate(this.center.x, this.center.y);
      ctx.rotate(angle(this.directionVector) - Math.PI / 2);
      ctx.scale(1, 3);

      ctx.beginPath();
      ctx.textBaseline = "middle";
      ctx.textAlign = "center";
      ctx.fillStyle = "white";
      ctx.font = "bold " + this.height * 0.3 + "px Arial";
      ctx.fillText("STOP", 0, 1);

      ctx.restore();
   }
}

// ───── world/js/markings/start.js ─────
class Start extends Marking {
   constructor(center, directionVector, width, height) {
      super(center, directionVector, width, height);

      this.type = "start";
      if (typeof document === "undefined") return;
      this.img = new Image();
      this.img.src = "car.png";
   }

   draw(ctx) {
      ctx.save();
      ctx.translate(this.center.x, this.center.y);
      ctx.rotate(angle(this.directionVector) - Math.PI / 2);
      
      ctx.drawImage(this.img, -this.img.width / 2, -this.img.height / 2);

      ctx.restore();
   }
}

// ───── world/js/markings/crossing.js ─────
class Crossing extends Marking {
   constructor(center, directionVector, width, height) {
      super(center, directionVector, width, height);

      this.borders = [this.poly.segments[0], this.poly.segments[2]];
      this.type = "crossing";
   }

   draw(ctx) {
      const perp = perpendicular(this.directionVector);
      const line = new Segment(
         add(this.center, scale(perp, this.width / 2)),
         add(this.center, scale(perp, -this.width / 2))
      );
      line.draw(ctx, {
         width: this.height,
         color: "white",
         dash: [11, 11]
      });
   }
}

// ───── world/js/markings/parking.js ─────
class Parking extends Marking {
   constructor(center, directionVector, width, height) {
      super(center, directionVector, width, height);

      this.borders = [this.poly.segments[0], this.poly.segments[2]];
      this.type = "parking";
   }

   draw(ctx) {
      for (const border of this.borders) {
         border.draw(ctx, { width: 5, color: "white" });
      }
      ctx.save();
      ctx.translate(this.center.x, this.center.y);
      ctx.rotate(angle(this.directionVector));

      ctx.beginPath();
      ctx.textBaseline = "middle";
      ctx.textAlign = "center";
      ctx.fillStyle = "white";
      ctx.font = "bold " + this.height * 0.9 + "px Arial";
      ctx.fillText("P", 0, 3);

      ctx.restore();
   }
}

// ───── world/js/markings/light.js ─────
class Light extends Marking {
   constructor(center, directionVector, width, height) {
      super(center, directionVector, width, 18);

      this.state = "off";
      this.border = this.poly.segments[0];
      this.type = "light";
   }

   draw(ctx) {
      const perp = perpendicular(this.directionVector);
      const line = new Segment(
         add(this.center, scale(perp, this.width / 2)),
         add(this.center, scale(perp, -this.width / 2))
      );

      const green = lerp2D(line.p1, line.p2, 0.2);
      const yellow = lerp2D(line.p1, line.p2, 0.5);
      const red = lerp2D(line.p1, line.p2, 0.8);

      new Segment(red, green).draw(ctx, {
         width: this.height,
         cap: "round"
      });

      green.draw(ctx, { size: this.height * 0.6, color: "#060" });
      yellow.draw(ctx, { size: this.height * 0.6, color: "#660" });
      red.draw(ctx, { size: this.height * 0.6, color: "#600" });

      switch (this.state) {
         case "green":
            green.draw(ctx, { size: this.height * 0.6, color: "#0F0" });
            break;
         case "yellow":
            yellow.draw(ctx, { size: this.height * 0.6, color: "#FF0" });
            break;
         case "red":
            red.draw(ctx, { size: this.height * 0.6, color: "#F00" });
            break;
      }
   }
}

