// ───── world/js/items/tree.js ─────
class Tree {
   constructor(center, size, height = 200) {
      this.center = center;
      this.size = size; // size of the base
      this.height = height;
      this.base = this.#generateLevel(center, size);
   }

   #generateLevel(point, size) {
      const points = [];
      const rad = size / 2;
      for (let a = 0; a < Math.PI * 2; a += Math.PI / 16) {
         const kindOfRandom = Math.cos(((a + this.center.x) * size) % 17) ** 2;
         const noisyRadius = rad * lerp(0.5, 1, kindOfRandom);
         points.push(translate(point, a, noisyRadius));
      }
      return new Polygon(points);
   }

   draw(ctx, viewPoint) {
      const top = getFake3dPoint(this.center, viewPoint, this.height);

      const levelCount = 7;
      for (let level = 0; level < levelCount; level++) {
         const t = level / (levelCount - 1);
         const point = lerp2D(this.center, top, t);
         const color = "rgb(30," + lerp(50, 200, t) + ",70)";
         const size = lerp(this.size, 40, t);
         const poly = this.#generateLevel(point, size);
         poly.draw(ctx, { fill: color, stroke: "rgba(0,0,0,0)" });
      }
   }
}

// ───── world/js/items/building.js ─────
class Building {
   constructor(poly, height = 200) {
      this.base = poly;
      this.height = height;
   }

   static load(info) {
      return new Building(Polygon.load(info.base), info.height);
   }

   draw(ctx, viewPoint) {
      const topPoints = this.base.points.map((p) =>
         getFake3dPoint(p, viewPoint, this.height * 0.6)
      );
      const ceiling = new Polygon(topPoints);

      const sides = [];
      for (let i = 0; i < this.base.points.length; i++) {
         const nextI = (i + 1) % this.base.points.length;
         const poly = new Polygon([
            this.base.points[i], this.base.points[nextI],
            topPoints[nextI], topPoints[i]
         ]);
         sides.push(poly);
      }
      sides.sort(
         (a, b) =>
            b.distanceToPoint(viewPoint) -
            a.distanceToPoint(viewPoint)
      );

      const baseMidpoints = [
         average(this.base.points[0], this.base.points[1]),
         average(this.base.points[2], this.base.points[3])
      ];

      const topMidpoints = baseMidpoints.map((p) =>
         getFake3dPoint(p, viewPoint, this.height)
      );

      const roofPolys = [
         new Polygon([
            ceiling.points[0], ceiling.points[3],
            topMidpoints[1], topMidpoints[0]
         ]),
         new Polygon([
            ceiling.points[2], ceiling.points[1],
            topMidpoints[0], topMidpoints[1]
         ])
      ];
      roofPolys.sort(
         (a, b) =>
            b.distanceToPoint(viewPoint) -
            a.distanceToPoint(viewPoint)
      );

      this.base.draw(ctx, { fill: "white", stroke: "rgba(0,0,0,0.2)", lineWidth: 20 });
      for (const side of sides) {
         side.draw(ctx, { fill: "white", stroke: "#AAA" });
      }
      ceiling.draw(ctx, { fill: "white", stroke: "white", lineWidth: 6 });
      for (const poly of roofPolys) {
         poly.draw(ctx, { fill: "#D44", stroke: "#C44", lineWidth: 8, join: "round" });
      }
   }
}

// ───── world/js/viewport.js ─────
class Viewport {
   constructor(canvas, zoom = 1, offset = null) {
      this.canvas = canvas;
      this.ctx = canvas.getContext("2d");

      this.zoom = zoom;
      this.center = new Point(canvas.width / 2, canvas.height / 2);
      this.offset = offset ? offset : scale(this.center, -1);

      this.drag = {
         start: new Point(0, 0),
         end: new Point(0, 0),
         offset: new Point(0, 0),
         active: false
      };

      this.#addEventListeners();
   }

   reset() {
      this.ctx.restore();
      this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
      this.ctx.save();
      this.ctx.translate(this.center.x, this.center.y);
      this.ctx.scale(1 / this.zoom, 1 / this.zoom);
      const offset = this.getOffset();
      this.ctx.translate(offset.x, offset.y);
   }

   getMouse(evt, subtractDragOffset = false) {
      const p = new Point(
         (evt.offsetX - this.center.x) * this.zoom - this.offset.x,
         (evt.offsetY - this.center.y) * this.zoom - this.offset.y
      );
      return subtractDragOffset ? subtract(p, this.drag.offset) : p;
   }

   getOffset() {
      return add(this.offset, this.drag.offset);
   }

   #addEventListeners() {
      this.canvas.addEventListener("mousewheel", this.#handleMouseWheel.bind(this));
      this.canvas.addEventListener("mousedown", this.#handleMouseDown.bind(this));
      this.canvas.addEventListener("mousemove", this.#handleMouseMove.bind(this));
      this.canvas.addEventListener("mouseup", this.#handleMouseUp.bind(this));
   }

   #handleMouseDown(evt) {
      if (evt.button == 1) { // middle button
         this.drag.start = this.getMouse(evt);
         this.drag.active = true;
      }
   }

   #handleMouseMove(evt) {
      if (this.drag.active) {
         this.drag.end = this.getMouse(evt);
         this.drag.offset = subtract(this.drag.end, this.drag.start);
      }
   }

   #handleMouseUp(evt) {
      if (this.drag.active) {
         this.offset = add(this.offset, this.drag.offset);
         this.drag = {
            start: new Point(0, 0),
            end: new Point(0, 0),
            offset: new Point(0, 0),
            active: false
         };
      }
   }

   #handleMouseWheel(evt) {
      const dir = Math.sign(evt.deltaY);
      const step = 0.1;
      this.zoom += dir * step;
      this.zoom = Math.max(1, Math.min(5, this.zoom));
   }
}

// ───── world/js/editors/markingEditor.js ─────
class MarkingEditor {
   constructor(viewport, world, targetSegments) {
      this.viewport = viewport;
      this.world = world;

      this.canvas = viewport.canvas;
      this.ctx = this.canvas.getContext("2d");

      this.mouse = null;
      this.intent = null;

      this.targetSegments = targetSegments;

      this.markings = world.markings;
   }

   // to be overwritten
   createMarking(center, directionVector) {
      return center;
   }

   enable() {
      this.#addEventListeners();
   }

   disable() {
      this.#removeEventListeners();
   }

   #addEventListeners() {
      this.boundMouseDown = this.#handleMouseDown.bind(this);
      this.boundMouseMove = this.#handleMouseMove.bind(this);
      this.boundContextMenu = (evt) => evt.preventDefault();
      this.canvas.addEventListener("mousedown", this.boundMouseDown);
      this.canvas.addEventListener("mousemove", this.boundMouseMove);
      this.canvas.addEventListener("contextmenu", this.boundContextMenu);
   }

   #removeEventListeners() {
      this.canvas.removeEventListener("mousedown", this.boundMouseDown);
      this.canvas.removeEventListener("mousemove", this.boundMouseMove);
      this.canvas.removeEventListener("contextmenu", this.boundContextMenu);
   }

   #handleMouseMove(evt) {
      this.mouse = this.viewport.getMouse(evt, true);
      const seg = getNearestSegment(
         this.mouse, 
         this.targetSegments, 
         10 * this.viewport.zoom
      );
      if (seg) {
         const proj = seg.projectPoint(this.mouse);
         if (proj.offset >= 0 && proj.offset <= 1) {
            this.intent = this.createMarking(
               proj.point,
               seg.directionVector()
            );
         } else {
            this.intent = null;
         }
      } else {
         this.intent = null;
      }
   }

   #handleMouseDown(evt) {
      if (evt.button == 0) { // left click
         if (this.intent) {
            this.markings.push(this.intent);
            this.intent = null;
         }
      }
      if (evt.button == 2) { // right click
         for (let i = 0; i < this.markings.length; i++) {
            const poly = this.markings[i].poly;
            if (poly.containsPoint(this.mouse)) {
               this.markings.splice(i, 1);
               return;
            }
         }
      }
   }

   display() {
      if (this.intent) {
         this.intent.draw(this.ctx);
      }
   }
}

// ───── world/js/editors/graphEditor.js ─────
class GraphEditor {
   constructor(viewport, graph) {
      this.viewport = viewport;
      this.canvas = viewport.canvas;
      this.graph = graph;

      this.ctx = this.canvas.getContext("2d");

      this.selected = null;
      this.hovered = null;
      this.dragging = false;
      this.mouse = null;
   }

   enable() {
      this.#addEventListeners();
   }

   disable() {
      this.#removeEventListeners();
      this.selected = false;
      this.hovered = false;
   }

   #addEventListeners() {
      this.boundMouseDown = this.#handleMouseDown.bind(this);
      this.boundMouseMove = this.#handleMouseMove.bind(this);
      this.boundMouseUp = () => this.dragging = false;
      this.boundContextMenu = (evt) => evt.preventDefault();
      this.canvas.addEventListener("mousedown", this.boundMouseDown);
      this.canvas.addEventListener("mousemove", this.boundMouseMove);
      this.canvas.addEventListener("mouseup", this.boundMouseUp);
      this.canvas.addEventListener("contextmenu", this.boundContextMenu);
   }

   #removeEventListeners() {
      this.canvas.removeEventListener("mousedown", this.boundMouseDown);
      this.canvas.removeEventListener("mousemove", this.boundMouseMove);
      this.canvas.removeEventListener("mouseup", this.boundMouseUp);
      this.canvas.removeEventListener("contextmenu", this.boundContextMenu);
   }

   #handleMouseMove(evt) {
      this.mouse = this.viewport.getMouse(evt, true);
      this.hovered = getNearestPoint(this.mouse, this.graph.points, 10 * this.viewport.zoom);
      if (this.dragging == true) {
         this.selected.x = this.mouse.x;
         this.selected.y = this.mouse.y;
      }
   }

   #handleMouseDown(evt) {
      if (evt.button == 2) { // right click
         if (this.selected) {
            this.selected = null;
         } else if (this.hovered) {
            this.#removePoint(this.hovered);
         }
      }
      if (evt.button == 0) { // left click
         if (this.hovered) {
            this.#select(this.hovered);
            this.dragging = true;
            return;
         }
         this.graph.addPoint(this.mouse);
         this.#select(this.mouse);
         this.hovered = this.mouse;
      }
   }

   #select(point) {
      if (this.selected) {
         this.graph.tryAddSegment(new Segment(this.selected, point));
      }
      this.selected = point;
   }

   #removePoint(point) {
      this.graph.removePoint(point);
      this.hovered = null;
      if (this.selected == point) {
         this.selected = null;
      }
   }

   dispose() {
      this.graph.dispose();
      this.selected = null;
      this.hovered = null;
   }

   display() {
      this.graph.draw(this.ctx);
      if (this.hovered) {
         this.hovered.draw(this.ctx, { fill: true });
      }
      if (this.selected) {
         const intent = this.hovered ? this.hovered : this.mouse;
         new Segment(this.selected, intent).draw(this.ctx, { dash: [3, 3] });
         this.selected.draw(this.ctx, { outline: true });
      }
   }
}

